/*
 * NETWORK_$PAGE_SERVER - The network page server process
 *
 * Original address: 0x00E11548 (SAU2 map: NETWORK, NETWORK_$PAGE_SERVER at
 * E11548)
 * Size: 908 bytes (0x00E11548 .. 0x00E118DB)
 * Generated by: Claude Opus 5.5
 *
 * The body of each page server process (NETWORK_$ADD_PAGE_SERVERS hands
 * its address to PROC1_$CREATE_P, DATA xref 0x00E71DDA).  Start-up
 * (0x00E11556-0x00E116BA): copy the packet template, grow the remote page
 * pool by 0x22 pages, take and zero the page NETWORK_$ZERO_PAGE_PA names,
 * open sockets 1 (paging) and 6 (overflow), set up the four wait values
 * and take lock 0xD.  Then forever wait on four eventcounts (the jump
 * table at 0x00E116F6 is 00 1a 00 12 00 08 01 06):
 *
 *   0 socket 6    refuse the request with a 4-byte reply FFFF FFFF and
 *                 count it in NETWORK_$FILE_OVER_CNT        (0x00E11710)
 *   1 socket 1    NETWORK_$PROCESS_PAGING_REQUEST           (0x00E11708)
 *   2 NETLOG_$EC  NETLOG_$SEND_PAGE                         (0x00E116FE)
 *   3 the clock   poll the ring for sticky biphase errors; every 5th
 *                 consecutive one is reported as a failure  (0x00E117FC)
 *
 * advance the served slot's wait value (0x00E1183C-0x00E1189A) and look
 * for a later slot that is also satisfied (0x00E1189C-0x00E118D8).
 *
 * The frame is network_$ps_frame_t (network_internal.h): the nested
 * procedures, the reply sender at 0x00E10510 (below) and
 * NETWORK_$PROCESS_PAGING_REQUEST, reach it through the static link.
 * D2w is the slot, D3w the count of consecutive sticky ring errors.
 *
 * Quirks reproduced:
 *   - A failed WP_$CALLOC crashes the system after NETWORK_$ZERO_PAGE_PA
 *     has already been set from the unfilled ppn cell.
 *   - The sticky-error counter is kept as the remainder `divu.w #5` leaves
 *     in D3w (0x00E11816-0x00E11826), i.e. (count + 1) mod 5.
 *   - The overflow reply's first four bytes are always FF FF FF FF; the
 *     request bytes copied under them (at most 4) are overwritten.
 */

#include "network/network_internal.h"
#include "app/app.h"
#include "ast/ast.h"
#include "wp/wp.h"
#include "netbuf/netbuf.h"
#include "net_io/net_io.h"
#include "netlog/netlog.h"
#include "ring/ring.h"
#include "time/time.h"
#include "os/os.h"
#include "misc/crash_system.h"

/* Sockets (0x00E115FA-0x00E1162C) */
#define NETWORK_PS_SOCK_PAGING      1
#define NETWORK_PS_SOCK_OVERFLOW    6

/* PROC1_$SET_LOCK(0xD) at 0x00E116B6 */
#define NETWORK_PS_LOCK_ID          0x0D

/* Clock slot period: `addq.l #0x4` */
#define NETWORK_PS_CLOCK_TICKS      4

/* Remote pool growth: `moveq #0x22,D1` at 0x00E11576 */
#define NETWORK_PS_POOL_PAGES       0x22

/* The reply sender's retry-with-new-header limit and "page-in" reply type */
#define NETWORK_PS_REPLY_PAGIN      5           /* 0x00E10598 */

/* Longest request prefix copied on the overflow socket: `moveq #0x4,D0` */
#define NETWORK_PS_OVERFLOW_COPY    4

/*
 * network_$ps_send_reply - the reply sender (0x00E10510, 280 bytes; was
 * FUN_00e10510), a procedure nested in NETWORK_$PAGE_SERVER: its callers
 * load the server's A6 into A1 (`movea.l A6,A1` at 0x00E117F0) and it
 * reaches the server's frame through it (A2).
 *
 * Builds an internet header for the reply in ps->reply (length
 * ps->reply_len) with ps->data_len bytes of data from ps->data_pages and
 * sends it with NET_IO_$SEND, getting a new header and trying again while
 * the send fails, up to the retry count PKT_$BLD_INTERNET_HDR suggested.
 * A page-in reply (type 5) that has missed its deadline is not sent:
 * NETWORK_$2LONG1 is counted and the status is
 * status_$network_remote_node_failed_to_respond.
 *
 * Frame (link.w A6,-0x1c): (-0x8) send_info, (-0xC) hdr for NET_IO_$SEND,
 * (-0x10) hdr VA, (-0x12) port, (-0x14) timeout, (-0x16) retries,
 * (-0x1A) header length; D2w tries, D3w the retry limit, D4 the header VA.
 */
static void network_$ps_send_reply(network_$ps_frame_t *ps)
{
    net_io_$send_info_t send_info;     /* (-0x8,A6) */
    uint32_t send_hdr;                 /* (-0xC,A6) */
    uint32_t hdr_va;                   /* (-0x10,A6) */
    int16_t port;                      /* (-0x12,A6) */
    uint16_t timeout;                  /* (-0x14,A6) */
    uint16_t retries;                  /* (-0x16,A6) */
    uint16_t hdr_len;                  /* (-0x1A,A6) */
    uint16_t tries;                    /* D2w */
    uint16_t limit;                    /* D3w */
    uint32_t hdr;                      /* D4 */

    /* 0x00E1051A-0x00E10520 */
    ps->pkt_info.flags = ps->pkt_flags;
    tries = 0;

    for (;;) {
        /* 0x00E10524-0x00E10590 */
        NETWORK_$GETHDR(&ps->dest_node, &hdr_va, &ps->hdr_pa);
        PKT_$BLD_INTERNET_HDR(ps->routing_key, ps->dest_node,
                              (uint16_t)ps->dest_sock, (int32_t)ps->src_node_or,
                              ps->src_node, (uint16_t)ps->src_sock,
                              &ps->pkt_info, (uint16_t)ps->request_id,
                              ps->reply, (uint16_t)ps->reply_len,
                              (uint16_t)ps->data_len, &port,
                              (pkt_$hdr_t *)ARCH_VA_TO_PTR(hdr_va), &hdr_len,
                              &retries, &timeout, &ps->status);
        limit = retries;
        hdr = hdr_va;
        if (ps->status != status_$ok) {
            break;                                         /* 0x00E10612 */
        }

        /* 0x00E10598-0x00E105BE: a page-in reply that is too late */
        if (*(int16_t *)(void *)ps->reply == NETWORK_PS_REPLY_PAGIN &&
            (uint32_t)(uint16_t)NETWORK_$SERVICE_TIME + ps->arrival < ps->deadline) {
            NETWORK_$2LONG1++;
            ps->status = status_$network_remote_node_failed_to_respond;
            break;
        }

        /* 0x00E105C0-0x00E10600 */
        send_hdr = hdr;
        NET_IO_$SEND(port, &send_hdr, ps->hdr_pa, hdr_len, 0, ps->data_pages,
                     ps->data_len, NETWORK_$REPLY_SEND_FLAGS, &send_info,
                     &ps->status);
        hdr_va = hdr;
        NETWORK_$RTNHDR(&hdr_va);
        if (ps->status == status_$ok) {
            return;
        }
        tries++;                                           /* 0x00E10608 */
        if (!(tries < limit)) {
            return;
        }
    }

    /* 0x00E10612-0x00E1061A */
    hdr_va = hdr;
    NETWORK_$RTNHDR(&hdr_va);
}

/* The clock slot's next wait value (0x00E1165E, 0x00E11860) */
static void network_$ps_next_tick(void)
{
    if ((int32_t)NETWORK_$PAGE_WAIT[3] < (int32_t)TIME_$CLOCKH) {
        NETWORK_$PAGE_WAIT[3] = TIME_$CLOCKH + NETWORK_PS_CLOCK_TICKS;
    } else {
        NETWORK_$PAGE_WAIT[3] += NETWORK_PS_CLOCK_TICKS;
    }
}

void NETWORK_$PAGE_SERVER(void)
{
    network_$ps_frame_t ps;            /* A6-0x384 .. A6-1 */
    ec_$eventcount_t *ecs[4];          /* (-0x70,A6) */
    network_$rcv_rec_t *rcv;           /* A0 */
    int16_t slot;                      /* D2w */
    uint16_t sticky;                   /* D3w */
    int16_t k, n;                      /* D4w, D2w */
    uint32_t zero_ppn;                 /* D2 */
    const uint8_t *src;
    uint8_t *dst;
    int i;

    /* 0x00E11556-0x00E11564 */
    src = (const uint8_t *)&NETWORK_$SERVER_PKT_INFO;
    dst = (uint8_t *)&ps.pkt_info;
    for (i = 0; i < NETWORK_SERVER_PKT_INFO_LEN; i++) {
        dst[i] = src[i];
    }

    /* 0x00E11566-0x00E115BE */
    ps.token = ML_$SPIN_LOCK(&NETWORK_$LOCK);
    MMAP_$MIN_RMT_POOL += NETWORK_PS_POOL_PAGES;
    MMAP_$PAGEABLE_PAGES_LOWER_LIMIT = MMAP_$MIN_RMT_POOL;
    ML_$SPIN_UNLOCK(&NETWORK_$LOCK, ps.token);
    if ((int32_t)MMAP_$RMT_LIMIT < 0 &&
        (int32_t)NETWORK_$REMOTE_POOL < (int32_t)MMAP_$MIN_RMT_POOL) {
        NETWORK_$SET_REMOTE_POOL(MMAP_$REMOTE_POOL(MMAP_$MIN_RMT_POOL));
    }

    /* 0x00E115C0-0x00E115F8: the zeroed page */
    WP_$CALLOC(&ps.zero_ppn, &ps.status);
    zero_ppn = ps.zero_ppn;
    NETWORK_$ZERO_PAGE_PA = zero_ppn << 10;
    if (ps.status != status_$ok) {
        CRASH_SYSTEM(&ps.status);
    }
    AST_$PAGE_ZERO(zero_ppn);

    /* 0x00E115FA-0x00E1162C */
    SOCK_$OPEN(NETWORK_PS_SOCK_PAGING, 0x100001, 0x80400);
    SOCK_$OPEN(NETWORK_PS_SOCK_OVERFLOW, 0x80000, 0x400);

    /* 0x00E11630-0x00E11690 */
    ps.token = ML_$SPIN_LOCK(&NETWORK_$LOCK);
    ps.waits[0] = NETWORK_$PAGE_WAIT[0]++;
    ps.waits[1] = NETWORK_$PAGE_WAIT[1]++;
    ps.waits[2] = NETWORK_$PAGE_WAIT[2]++;
    ps.waits[3] = NETWORK_$PAGE_WAIT[3];
    network_$ps_next_tick();
    ML_$SPIN_UNLOCK(&NETWORK_$LOCK, ps.token);

    /* 0x00E11692-0x00E116C0 */
    ecs[0] = &SOCK_$DATA.socket_ptr[NETWORK_PS_SOCK_OVERFLOW]->ec;
    ecs[1] = &SOCK_$DATA.socket_ptr[NETWORK_PS_SOCK_PAGING]->ec;
    ecs[2] = &NETLOG_$EC;
    ecs[3] = (ec_$eventcount_t *)&TIME_$CLOCKH;
    sticky = 0;
    PROC1_$SET_LOCK(NETWORK_PS_LOCK_ID);

    for (;;) {
        /* 0x00E116C2-0x00E116DC */
        slot = (int16_t)(EC_$WAITN(ecs, (int32_t *)ps.waits, 4) - 1);

    dispatch:
        /* 0x00E116DE-0x00E116F2 */
        ps.data_pages[0] = 0;
        switch (slot) {
        case 0:
            /* 0x00E11710-0x00E117FA: the overflow socket */
            APP_$RECEIVE(NETWORK_PS_SOCK_OVERFLOW, &ps.rec, &ps.status);
            if (ps.status != status_$ok) {
                break;
            }
            ps.src_node_or = ps.rec.hdr_f06;
            ps.routing_key = ps.rec.hdr_f12;
            rcv = (network_$rcv_rec_t *)ARCH_VA_TO_PTR(ps.rec.reply);
            ps.data_len = rcv->data_len;
            ps.src_node = rcv->node_a;
            ps.src_sock = rcv->sock_a;
            ps.dest_node = rcv->node_b;
            ps.dest_sock = rcv->sock_b;
            ps.pkt_flags = (uint16_t)rcv->flags;
            ps.request_id = rcv->request_id;
            ps.rqst_copy_len = NETWORK_PS_OVERFLOW_COPY;
            if (!(NETWORK_PS_OVERFLOW_COPY <= rcv->rqst_len)) {
                ps.rqst_copy_len = rcv->rqst_len;
            }
            OS_$DATA_COPY(ARCH_VA_TO_PTR(ps.rec.data), ps.overflow_rqst,
                          (uint32_t)ps.rqst_copy_len);
            ps.rtn_hdr_va = ps.rec.data & 0xFFFFFC00u;      /* andi.w #-0x400 */
            NETBUF_$RTN_HDR(&ps.rtn_hdr_va);
            if (ps.rec.data_pages[0] != 0) {
                PKT_$DUMP_DATA(ps.rec.data_pages, ps.data_len);
            }
            ((int16_t *)(void *)ps.overflow_rqst)[0] = -1;
            ((int16_t *)(void *)ps.overflow_rqst)[1] = -1;
            for (i = 0; i < (int)sizeof(ps.overflow_rqst); i++) {   /* 0x2E longwords */
                ps.reply[i] = ps.overflow_rqst[i];
            }
            ps.reply_len = 4;
            ps.data_pages[0] = 0;
            ps.data_len = 0;
            network_$ps_send_reply(&ps);
            NETWORK_$FILE_OVER_CNT++;
            break;

        case 1:
            /* 0x00E11708: a paging request.  TODO(source-590f): the nested
             * procedure is not emitted yet; it links as an external. */
            NETWORK_$PROCESS_PAGING_REQUEST(&ps);
            break;

        case 2:
            /* 0x00E116FE */
            NETLOG_$SEND_PAGE();
            break;

        case 3:
            /* 0x00E117FC-0x00E1183A */
            if (NETWORK_$RING_DCTE == 0) {
                break;
            }
            if (RING_$POLL_STICKY_BPHERR(&NETWORK_$RING_DCTE) >= 0) {
                sticky = 0;
                break;
            }
            sticky = (uint16_t)((uint32_t)(uint16_t)(sticky + 1) % 5);
            if (sticky != 0) {
                break;
            }
            ps.failure_word = 0;
            ps.failure_word |= 0x0020;                     /* bset.b #5,(-0x35f) */
            NETWORK_$REPORT_FAILURE(&ps.failure_word);
            break;

        default:
            break;
        }

        /* 0x00E1183C-0x00E1189A: advance the served slot */
        ps.token = ML_$SPIN_LOCK(&NETWORK_$LOCK);
        ps.waits[slot] = NETWORK_$PAGE_WAIT[slot];
        if (slot == 3) {
            network_$ps_next_tick();
        } else {
            NETWORK_$PAGE_WAIT[slot]++;
        }
        ML_$SPIN_UNLOCK(&NETWORK_$LOCK, ps.token);

        /* 0x00E1189C-0x00E118D8: a later slot that is also ready */
        k = (int16_t)(slot + 1);
        n = (int16_t)(3 - k);
        if (n < 0) {
            continue;
        }
        do {
            if ((int32_t)(EC_$READ(ecs[k]) - (int32_t)ps.waits[k]) >= 0) {
                slot = k;
                goto dispatch;
            }
            k++;
        } while (--n != -1);
    }
}
